import{_ as o,o as t,c as r,a2 as i}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Introduction","description":"LitePHP is a Laravel-inspired PHP 8.1+ framework with zero runtime dependencies. Build web apps and APIs with familiar conventions and a small footprint.","frontmatter":{"title":"Introduction","description":"LitePHP is a Laravel-inspired PHP 8.1+ framework with zero runtime dependencies. Build web apps and APIs with familiar conventions and a small footprint."},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md"}'),a={name:"introduction.md"};function n(s,e,d,c,l,u){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><blockquote><p>LitePHP is a Laravel-inspired PHP 8.1+ framework with zero runtime dependencies. Build web apps and APIs with familiar conventions and a small footprint.</p></blockquote><p>LitePHP is a Laravel-inspired PHP framework designed for developers who want familiar, expressive conventions without pulling in hundreds of third-party packages. It requires PHP 8.1 or higher, carries <strong>zero runtime dependencies</strong>, and ships everything you need — routing, an ActiveRecord-style ORM, session and JWT authentication, request validation, a queue system, a template engine, security defaults, and a code-generation CLI — as one cohesive, MIT-licensed package.</p><h3 id="feature-highlights" tabindex="-1">Feature highlights <a class="header-anchor" href="#feature-highlights" aria-label="Permalink to &quot;Feature highlights&quot;">​</a></h3><ul><li><strong>Routing</strong> — Expressive route definitions for both web and API endpoints, with support for middleware, route groups, named routes, and parameter constraints.</li><li><strong>ORM &amp; Database</strong> — An ActiveRecord-style ORM with a fluent query builder, relationship support, and PDO-backed connections to MySQL and SQLite.</li><li><strong>Authentication</strong> — Session-based auth for web apps and JWT or token-based auth for APIs — all configured through a single <code>auth.php</code> file and your <code>.env</code>.</li><li><strong>Validation</strong> — Declarative, rule-based request validation with automatic error collection, keeping your controllers clean and free of manual checks.</li><li><strong>Queue System</strong> — Dispatch background jobs to a queue and process them asynchronously via the <code>lite queue:work</code> CLI command — no separate broker required.</li><li><strong>Template Engine</strong> — The <code>.lites</code> template engine compiles views to plain PHP with automatic escaping. View caching is toggled with a single <code>VIEW_CACHE</code> env flag.</li><li><strong>Security Defaults</strong> — CSRF protection, configurable CORS middleware, secure session cookies, and a boot-time guard that prevents running with <code>APP_DEBUG=true</code> in production.</li><li><strong>CLI Tools</strong> — The <code>lite</code> command-line tool generates controllers, models, services, migrations, jobs, and more — so you spend time writing logic, not boilerplate.</li></ul><h3 id="who-is-litephp-for" tabindex="-1">Who is LitePHP for? <a class="header-anchor" href="#who-is-litephp-for" aria-label="Permalink to &quot;Who is LitePHP for?&quot;">​</a></h3><p><strong>Developers learning modern PHP.</strong> If you want to understand how a real framework works — dependency injection, middleware pipelines, an ORM, route caching — LitePHP&#39;s small codebase gives you a clear view. You get Laravel-like ergonomics without the learning curve of navigating a multi-thousand-file monorepo.</p><p><strong>Teams building focused applications.</strong> When you&#39;re building a REST API, a headless back-end, or a modest web app and you don&#39;t need the full surface area of Laravel or Symfony, LitePHP lets you move fast, keep your <code>vendor/</code> lean, and own every layer of your stack.</p><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Requirement</th><th>Minimum version</th></tr></thead><tbody><tr><td>PHP</td><td>8.1</td></tr><tr><td>Composer</td><td>2.x</td></tr><tr><td>Database</td><td>MySQL 5.7+ or SQLite 3</td></tr><tr><td>Web server</td><td>Apache, Nginx, or PHP&#39;s built-in server</td></tr></tbody></table><h3 id="architecture-overview" tabindex="-1">Architecture overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture overview&quot;">​</a></h3><p>Every HTTP request to a LitePHP application travels through the same ordered pipeline, defined in <code>Core/Bootstrap/app.php</code>:</p><ol><li><strong>Autoloader</strong> — The PSR-4 autoloader maps the <code>Core\\</code> namespace to <code>Core/</code> and the <code>App\\</code> namespace to <code>app/</code>, making all framework and application classes available without manual <code>require</code> calls.</li><li><strong>Environment</strong> — <code>Core\\Config\\Env</code> parses your <code>.env</code> file line-by-line, strips surrounding quotes, and populates both <code>$_ENV</code> and an internal static registry. Values are accessible anywhere via the <code>env()</code> helper.</li><li><strong>Config</strong> — <code>Core\\Config\\Config::load()</code> reads every file under <code>Core/Config/defaults/</code>, then merges any matching files from your project&#39;s <code>config/</code> directory on top using <code>array_replace_recursive</code>. This means you only override the keys you care about.</li><li><strong>Cache</strong> — The file cache driver boots and creates its storage directory if needed.</li><li><strong>Container</strong> — An IoC container is instantiated and the core services (<code>Request</code>, <code>Response</code>, <code>Router</code>, <code>Database</code>) are registered as singletons or instances.</li><li><strong>Facade</strong> — The <code>Route</code> facade is wired to the <code>Router</code> instance so you can call <code>Route::get()</code> anywhere in your route files.</li><li><strong>Session</strong> — The session save path is set to <code>storage/framework/sessions/</code>, the session is started, and the <code>Session</code> alias is bound into the container.</li><li><strong>Auth</strong> — <code>Auth::configure()</code> reads <code>config/auth.php</code> and registers your User model, field names, and JWT settings.</li><li><strong>Middleware</strong> — The <code>Kernel</code> runs <code>autoDiscover()</code> to scan <code>app/Middleware/</code> for classes carrying a <code>#[RegisterMiddleware]</code> attribute, then wraps every request with CSRF verification and any route-matched middleware.</li><li><strong>Router</strong> — The <code>Router</code> matches the incoming URI and HTTP method against your registered routes. In production, routes are loaded from a file cache keyed to your app name, skipping the cost of re-parsing <code>web.php</code> on every request.</li><li><strong>Controller → Response</strong> — The matched route&#39;s handler (a closure or controller method) is invoked and returns a <code>Response</code> object, which the <code>Kernel</code> sends back to the browser.</li></ol><blockquote><p><strong>Tip:</strong> LitePHP enforces a production safety guard during bootstrap: if both <code>APP_ENV=production</code> and <code>APP_DEBUG=true</code> are set in your <code>.env</code>, the application throws a <code>RuntimeException</code> immediately and refuses to serve requests. This prevents accidentally exposing detailed stack traces to end users. Always set <code>APP_DEBUG=false</code> before deploying.</p></blockquote>',14)])])}const g=o(a,[["render",n]]);export{p as __pageData,g as default};
